(function(){
 function hexToRgb(hex){hex=hex.replace('#','');let b=parseInt(hex,16);return [(b>>16)&255,(b>>8)&255,b&255];}
 let frostRgb=hexToRgb(PALETTE[1]||'#d7e8ec');
 let goldRgb=hexToRgb(PALETTE[2]||'#e8a853');
 let berryRgb=hexToRgb(PALETTE[0]||'#a31e34');
 let particles=[],glints=[],berries=[];
 let w=W(),h=H();
 function init(){
  particles=[];
  let count=170;
  for(let i=0;i<count;i++){
   particles.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.6+0.4,speed:Math.random()*0.14+0.03,drift:Math.random()*0.6-0.3,phase:Math.random()*Math.PI*2,alpha:Math.random()*0.5+0.3});
  }
  glints=[];
  for(let i=0;i<10;i++){
   let top=Math.random()<0.5;
   glints.push({x:Math.random()*w,y: top?Math.random()*h*0.26:h*0.74+Math.random()*h*0.26,r:Math.random()*2.5+1.8,phase:Math.random()*Math.PI*2,speed:Math.random()*0.018+0.008});
  }
  berries=[];
  for(let i=0;i<6;i++){
   let top=Math.random()<0.5;
   berries.push({x:Math.random()*w,y: top?Math.random()*h*0.2:h*0.8+Math.random()*h*0.2,r:Math.random()*2+2,phase:Math.random()*Math.PI*2});
  }
 }
 init();
 let t=0;
 function frame(){
  t+=1;
  w=W(); h=H();
  ctx.clearRect(0,0,w,h);
  for(let p of particles){
   p.y+=p.speed;
   p.x+=Math.sin(t*0.008+p.phase)*p.drift*0.05;
   if(p.y>h){p.y=-4;p.x=Math.random()*w;}
   let centerDist=Math.abs(p.y-h*0.5)/(h*0.5);
   let fade=Math.min(1,centerDist*1.9);
   let a=p.alpha*fade*(0.5+0.5*Math.sin(t*0.02+p.phase));
   ctx.beginPath();
   ctx.fillStyle=`rgba(${frostRgb[0]},${frostRgb[1]},${frostRgb[2]},${a})`;
   ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
   ctx.fill();
  }
  for(let g of glints){
   let a=0.35+0.35*Math.sin(t*g.speed+g.phase);
   let grad=ctx.createRadialGradient(g.x,g.y,0,g.x,g.y,g.r*7);
   grad.addColorStop(0,`rgba(${goldRgb[0]},${goldRgb[1]},${goldRgb[2]},${a*0.55})`);
   grad.addColorStop(1,`rgba(${goldRgb[0]},${goldRgb[1]},${goldRgb[2]},0)`);
   ctx.fillStyle=grad;
   ctx.beginPath();
   ctx.arc(g.x,g.y,g.r*7,0,Math.PI*2);
   ctx.fill();
   ctx.beginPath();
   ctx.fillStyle=`rgba(255,240,210,${a})`;
   ctx.arc(g.x,g.y,g.r*0.5,0,Math.PI*2);
   ctx.fill();
  }
  for(let b of berries){
   let pulse=0.6+0.4*Math.sin(t*0.015+b.phase);
   ctx.beginPath();
   ctx.fillStyle=`rgba(${berryRgb[0]},${berryRgb[1]},${berryRgb[2]},${0.55*pulse})`;
   ctx.arc(b.x,b.y,b.r,0,Math.PI*2);
   ctx.fill();
   ctx.beginPath();
   ctx.fillStyle=`rgba(255,255,255,${0.4*pulse})`;
   ctx.arc(b.x-b.r*0.3,b.y-b.r*0.3,b.r*0.3,0,Math.PI*2);
   ctx.fill();
  }
  requestAnimationFrame(frame);
 }
 requestAnimationFrame(frame);
})();
